import React, { useState, useEffect } from 'react'
import { supabase } from '../supabase'
import LabResults from './LabResults'
import IntakeSurvey from './IntakeSurvey'
import WeeklyCheckin from './WeeklyCheckin'
import ReintroductionSurvey from './ReintroductionSurvey'
import SlipupSurvey from './SlipupSurvey'
import ComplianceAudit from './ComplianceAudit'
import DailyComplianceDisplay from './DailyComplianceDisplay'

const s = {
  wrap: { minHeight: '100vh', background: '#FAF8F4', display: 'flex', flexDirection: 'column' },
  nav: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 22px', height: '56px', background: '#FFFFFF', borderBottom: '1px solid rgba(0,0,0,0.08)', position: 'sticky', top: 0, zIndex: 10 },
  logo: { fontFamily: 'Fraunces, serif', fontSize: '19px', fontWeight: 500, color: '#1C1C1C' },
  logoEm: { color: '#3D5C3C', fontStyle: 'italic' },
  navPill: { fontSize: '11px', color: '#7A7A72', background: '#EDF3ED', padding: '4px 11px', borderRadius: '20px', fontWeight: 500 },
  logoutBtn: { background: 'none', border: 'none', fontSize: '12px', color: '#7A7A72', cursor: 'pointer', padding: '4px 8px' },
  content: { flex: 1, padding: '20px 20px 88px' },
  greeting: { fontFamily: 'Fraunces, serif', fontSize: '23px', fontWeight: 300, marginBottom: '3px' },
  greetingEm: { fontStyle: 'italic', color: '#3D5C3C' },
  sub: { fontSize: '13px', color: '#7A7A72', marginBottom: '18px' },

  // Action cards
  actionCard: { background: '#FFFFFF', border: '1.5px solid #3D5C3C', borderRadius: '14px', padding: '17px', marginBottom: '13px' },
  actionTag: { fontSize: '10px', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.6px', color: '#3D5C3C', background: '#EDF3ED', padding: '3px 8px', borderRadius: '20px', display: 'inline-block', marginBottom: '9px' },
  actionTagAmber: { fontSize: '10px', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.6px', color: '#D4894A', background: '#FDF2EA', padding: '3px 8px', borderRadius: '20px', display: 'inline-block', marginBottom: '9px' },
  actionTitle: { fontFamily: 'Fraunces, serif', fontSize: '17px', fontWeight: 300, marginBottom: '5px' },
  actionTitleEm: { fontStyle: 'italic', color: '#3D5C3C' },
  actionSub: { fontSize: '12px', color: '#7A7A72', lineHeight: 1.6, marginBottom: '13px' },
  actionBtn: { background: '#3D5C3C', color: 'white', border: 'none', borderRadius: '9px', padding: '10px 18px', fontSize: '13px', fontWeight: 500, cursor: 'pointer', fontFamily: 'DM Sans, sans-serif' },
  actionBtnAmber: { background: '#D4894A', color: 'white', border: 'none', borderRadius: '9px', padding: '10px 18px', fontSize: '13px', fontWeight: 500, cursor: 'pointer', fontFamily: 'DM Sans, sans-serif' },

  // Pending card
  pendingCard: { background: '#FDF2EA', border: '1px solid rgba(212,137,74,0.2)', borderRadius: '12px', padding: '14px', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '11px' },
  pendingIcon: { width: '34px', height: '34px', background: '#D4894A', borderRadius: '9px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 },

  // Audit pending card
  auditPendingCard: { background: '#FAF8F4', border: '1px solid rgba(0,0,0,0.08)', borderRadius: '12px', padding: '14px', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '11px' },
  auditIcon: { width: '34px', height: '34px', background: '#EDF3ED', borderRadius: '9px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 },

  // Phase card
  phaseCard: { background: '#3D5C3C', borderRadius: '14px', padding: '17px', color: 'white', marginBottom: '12px' },
  phaseLabel: { fontSize: '10px', fontWeight: 600, letterSpacing: '0.8px', textTransform: 'uppercase', opacity: 0.65, marginBottom: '4px' },
  phaseTitle: { fontFamily: 'Fraunces, serif', fontSize: '17px', fontWeight: 300, marginBottom: '10px' },
  pbar: { background: 'rgba(255,255,255,0.2)', borderRadius: '3px', height: '4px', marginBottom: '6px', overflow: 'hidden' },
  pfill: { height: '100%', background: 'white', borderRadius: '3px' },
  plabel: { fontSize: '10px', opacity: 0.75, display: 'flex', justifyContent: 'space-between' },

  // Stat cards
  cards2: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '9px', marginBottom: '12px' },
  scard: { background: '#FFFFFF', border: '1px solid rgba(0,0,0,0.08)', borderRadius: '9px', padding: '12px' },
  slabel: { fontSize: '10px', color: '#7A7A72', fontWeight: 500, textTransform: 'uppercase', letterSpacing: '0.4px', marginBottom: '4px' },
  sval: { fontFamily: 'Fraunces, serif', fontSize: '24px', fontWeight: 300 },
  ssub: { fontSize: '10px', color: '#7A7A72', marginTop: '2px' },

  // Avoiding list
  secLabel: { fontSize: '11px', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.6px', color: '#7A7A72', marginBottom: '8px' },
  listCard: { background: '#FFFFFF', border: '1px solid rgba(0,0,0,0.08)', borderRadius: '10px', overflow: 'hidden', marginBottom: '12px' },
  listItem: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 13px', fontSize: '13px' },
  listLeft: { display: 'flex', alignItems: 'center', gap: '8px' },
  dot: { width: '7px', height: '7px', borderRadius: '50%', flexShrink: 0 },
  badge: { fontSize: '11px', fontWeight: 500, padding: '3px 9px', borderRadius: '20px' },

  // Insight
  insight: { background: '#FFFFFF', border: '1px solid rgba(0,0,0,0.08)', borderRadius: '10px', padding: '13px', marginBottom: '12px' },
  itag: { fontSize: '11px', fontWeight: 600, letterSpacing: '0.5px', textTransform: 'uppercase', color: '#3D5C3C', background: '#EDF3ED', padding: '3px 8px', borderRadius: '20px', display: 'inline-block', marginBottom: '7px' },
  itext: { fontSize: '13px', lineHeight: 1.65 },

  // Bottom nav
  bottomNav: { position: 'fixed', bottom: 0, left: 0, right: 0, display: 'flex', background: '#FFFFFF', borderTop: '1px solid rgba(0,0,0,0.08)', padding: '10px 0 6px' },
  bnItem: { flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '3px', cursor: 'pointer', padding: '3px 0' },
  bnLabel: { fontSize: '10px', fontWeight: 500, color: '#7A7A72' },
  bnLabelActive: { fontSize: '10px', fontWeight: 500, color: '#3D5C3C' },
  loadingWrap: { flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#7A7A72', fontSize: '14px' },
}

const BADGE = {
  High: { bg: '#FAEAEA', color: '#C95B5B', dot: '#C95B5B' },
  Moderate: { bg: '#FDF2EA', color: '#D4894A', dot: '#D4894A' },
  Low: { bg: '#EAF4EE', color: '#4A8C6A', dot: '#4A8C6A' },
}

export default function Dashboard({ session, onLogout }) {
  const [screen, setScreen] = useState('dashboard')
  const [tab, setTab] = useState('home')
  const [profile, setProfile] = useState(null)
  const [labResult, setLabResult] = useState(null)
  const [weeklyDue, setWeeklyDue] = useState(false)
  const [complianceData, setComplianceData] = useState([])
  const [consecutiveNOs, setConsecutiveNOs] = useState(0)
  const [pendingAudit, setPendingAudit] = useState(false)
  const [loading, setLoading] = useState(true)

  const name = session?.user?.user_metadata?.full_name?.split(' ')[0] || 'there'

  const getGreeting = () => {
    const h = new Date().getHours()
    if (h < 12) return 'Good morning'
    if (h < 17) return 'Good afternoon'
    return 'Good evening'
  }

  useEffect(() => { loadData() }, [screen])

  const loadData = async () => {
    setLoading(true)
    try {
      const { data: p } = await supabase.from('profiles').select('*').eq('id', session.user.id).single()
      setProfile(p)

      const { data: l } = await supabase.from('lab_results').select('*').eq('user_id', session.user.id).order('submitted_at', { ascending: false }).limit(1).single()
      setLabResult(l)

      // Load last 7 days compliance
      const sevenDaysAgo = new Date()
      sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7)
      const { data: comp } = await supabase.from('daily_compliance').select('*').eq('user_id', session.user.id).gte('date', sevenDaysAgo.toISOString().split('T')[0]).order('date', { ascending: false })
      if (comp) {
        setComplianceData(comp)
        // Count consecutive NOs
        let nos = 0
        for (const entry of comp) {
          if (entry.response === 'NO') nos++
          else break
        }
        setConsecutiveNOs(nos)
      }

      // Check for pending audit
      const { data: audit } = await supabase.from('compliance_audit').select('*').eq('user_id', session.user.id).eq('status', 'pending_admin_review').single()
      setPendingAudit(!!audit)

      // Check for today's compliance
      const today = new Date().toISOString().split('T')[0]
      const todayEntry = comp?.find(c => c.date === today)
      const slipupToday = todayEntry?.response === 'NO' && !todayEntry?.slip_up_logged

      if (p?.program_phase === 'elimination' || p?.program_phase === 'reintroduction') {
        const { data: c } = await supabase.from('weekly_checkins').select('submitted_at').eq('user_id', session.user.id).order('submitted_at', { ascending: false }).limit(1).single()
        if (!c) setWeeklyDue(true)
        else setWeeklyDue((new Date() - new Date(c.submitted_at)) / (1000 * 60 * 60 * 24) >= 7)
      }
    } catch (e) {}
    setLoading(false)
  }

  // Calculate clean days streak
  const cleanDays = (() => {
    let count = 0
    const sorted = [...complianceData].sort((a, b) => new Date(b.date) - new Date(a.date))
    for (const entry of sorted) {
      if (entry.response === 'YES') count++
      else break
    }
    return count
  })()

  // Today's slip-up pending
  const today = new Date().toISOString().split('T')[0]
  const todayEntry = complianceData.find(c => c.date === today)
  const showSlipupCard = todayEntry?.response === 'NO' && !pendingAudit
  const showAuditCard = consecutiveNOs >= 3 && !pendingAudit

  const showIntakeCard = !profile?.intake_completed_at
  const showLabCard = profile?.intake_completed_at && !labResult
  const showPendingLabCard = labResult?.status === 'pending_review'
  const showCheckinCard = weeklyDue && !showIntakeCard && !showLabCard && !showSlipupCard && !showAuditCard
  const showReintroCard = profile?.program_phase === 'reintroduction' && profile?.current_reintro_day >= 14

  const phaseLabel = profile?.program_phase === 'elimination' ? 'Elimination Phase'
    : profile?.program_phase === 'reintroduction' ? 'Reintroduction Phase'
    : profile?.program_phase === 'pending_review' ? 'Awaiting Approval'
    : 'Setup in progress'

  // Screen routing
  if (screen === 'intake') return <IntakeSurvey session={session} onBack={() => setScreen('dashboard')} onComplete={() => setScreen('dashboard')} />
  if (screen === 'labresults') return <LabResults session={session} onBack={() => setScreen('dashboard')} onComplete={() => setScreen('dashboard')} />
  if (screen === 'checkin') return <WeeklyCheckin session={session} weekNumber={profile?.current_week || 1} symptoms={profile?.symptoms || []} baselineScores={{ bloating: profile?.baseline_bloating, energy: profile?.baseline_energy }} currentFoods={labResult?.foods?.map(f => f.name) || []} phase={profile?.program_phase || 'elimination'} onBack={() => setScreen('dashboard')} onComplete={() => { setWeeklyDue(false); setScreen('dashboard') }} />
  if (screen === 'slipup') return <SlipupSurvey session={session} onBack={() => setScreen('dashboard')} onComplete={() => setScreen('dashboard')} />
  if (screen === 'audit') return <ComplianceAudit session={session} eliminatedFoods={labResult?.foods?.map(f => f.name) || []} onBack={() => setScreen('dashboard')} onComplete={() => setScreen('dashboard')} />
  if (screen === 'reintro-survey') return <ReintroductionSurvey session={session} food={profile?.current_reintro_food || 'Eggs'} cycleNumber={profile?.reintro_cycle || 1} baselineScores={{ bloating: profile?.baseline_bloating, energy: profile?.baseline_energy }} symptoms={profile?.symptoms || []} onBack={() => setScreen('dashboard')} onComplete={() => setScreen('dashboard')} />

  return (
    <div style={s.wrap}>
      <div style={s.nav}>
        <div style={s.logo}>sensi<em style={s.logoEm}>fy</em></div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <div style={s.navPill}>{phaseLabel}</div>
          <button style={s.logoutBtn} onClick={onLogout}>Sign out</button>
        </div>
      </div>

      {loading ? (
        <div style={s.loadingWrap}>Loading your program...</div>
      ) : (
        <div style={s.content}>
          <div style={s.greeting}>{getGreeting()}, <em style={s.greetingEm}>{name}.</em></div>
          <div style={s.sub}>
            {showIntakeCard ? "Welcome to Sensify. Let's get you set up."
              : showAuditCard ? "Let's talk about the last few days."
              : showSlipupCard ? "We logged a slip-up today. Tell us what happened."
              : showLabCard ? 'Your intake is complete. Upload your lab results to begin.'
              : showPendingLabCard ? 'Your results are under review.'
              : "You're making real progress. Keep going."}
          </div>

          {/* INTAKE CARD */}
          {showIntakeCard && (
            <div style={s.actionCard}>
              <div style={s.actionTag}>Complete your setup</div>
              <div style={s.actionTitle}>Start your <em style={s.actionTitleEm}>intake survey.</em></div>
              <div style={s.actionSub}>Tell us about your symptoms and how often you eat certain foods. Takes about 5 minutes and personalizes your entire program.</div>
              <button style={s.actionBtn} onClick={() => setScreen('intake')}>Start intake survey →</button>
            </div>
          )}

          {/* LAB RESULTS CARD */}
          {showLabCard && (
            <div style={s.actionCard}>
              <div style={s.actionTag}>Action needed</div>
              <div style={s.actionTitle}>Upload your <em style={s.actionTitleEm}>lab results.</em></div>
              <div style={s.actionSub}>PDF, photo, or manual entry — the AI reads your results and builds your elimination list in seconds.</div>
              <button style={s.actionBtn} onClick={() => setScreen('labresults')}>Upload results →</button>
            </div>
          )}

          {/* PENDING LAB REVIEW */}
          {showPendingLabCard && (
            <div style={s.pendingCard}>
              <div style={s.pendingIcon}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
              </div>
              <div>
                <div style={{ fontSize: '13px', fontWeight: 500, marginBottom: '2px' }}>Results under review</div>
                <div style={{ fontSize: '12px', color: '#7A7A72' }}>We'll notify you within 24 hours once your protocol is approved.</div>
              </div>
            </div>
          )}

          {/* AUDIT CARD — highest priority */}
          {showAuditCard && (
            <div style={{ ...s.actionCard, borderColor: '#D4894A' }}>
              <div style={s.actionTagAmber}>3 days off plan</div>
              <div style={s.actionTitle}>Let's <em style={{ fontStyle: 'italic', color: '#D4894A' }}>figure this out together.</em></div>
              <div style={s.actionSub}>Three days in a row is hard. Let's not treat it as failure — let's treat it as information. Takes about 3 minutes.</div>
              <button style={s.actionBtnAmber} onClick={() => setScreen('audit')}>Let's talk →</button>
            </div>
          )}

          {/* PENDING AUDIT REVIEW */}
          {pendingAudit && (
            <div style={s.auditPendingCard}>
              <div style={s.auditIcon}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#3D5C3C" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
              </div>
              <div>
                <div style={{ fontSize: '13px', fontWeight: 500, marginBottom: '2px' }}>Guidance being prepared</div>
                <div style={{ fontSize: '12px', color: '#7A7A72' }}>We're reviewing your audit responses. Your personalized guidance will be ready within 24 hours.</div>
              </div>
            </div>
          )}

          {/* SLIP-UP CARD */}
          {showSlipupCard && (
            <div style={{ ...s.actionCard, borderColor: 'rgba(201,91,91,0.4)' }}>
              <div style={{ ...s.actionTag, color: '#C95B5B', background: '#FAEAEA' }}>Slip-up logged today</div>
              <div style={s.actionTitle}>What <em style={{ fontStyle: 'italic', color: '#C95B5B' }}>happened today?</em></div>
              <div style={s.actionSub}>Takes 60 seconds. No judgment — just data that makes your AI insights more accurate.</div>
              <button style={{ ...s.actionBtn, background: '#C95B5B' }} onClick={() => setScreen('slipup')}>Tell us what happened →</button>
            </div>
          )}

          {/* WEEKLY CHECK-IN CARD */}
          {showCheckinCard && (
            <div style={s.actionCard}>
              <div style={s.actionTag}>Due now</div>
              <div style={s.actionTitle}>Your weekly <em style={s.actionTitleEm}>check-in.</em></div>
              <div style={s.actionSub}>Takes 2 minutes. The AI uses your answers to generate this week's personalized insight.</div>
              <button style={s.actionBtn} onClick={() => setScreen('checkin')}>Start check-in →</button>
            </div>
          )}

          {/* REINTRO VERDICT CARD */}
          {showReintroCard && (
            <div style={s.actionCard}>
              <div style={s.actionTag}>Day 14 — verdict ready</div>
              <div style={s.actionTitle}><em style={s.actionTitleEm}>{profile?.current_reintro_food}</em> reintroduction complete.</div>
              <div style={s.actionSub}>Complete your survey and get your AI verdict — Safe, Limit, or Avoid.</div>
              <button style={s.actionBtn} onClick={() => setScreen('reintro-survey')}>Get my verdict →</button>
            </div>
          )}

          {/* PHASE CARD */}
          <div style={s.phaseCard}>
            <div style={s.phaseLabel}>Your program</div>
            <div style={s.phaseTitle}>{phaseLabel}</div>
            <div style={s.pbar}>
              <div style={{ ...s.pfill, width: profile?.program_phase === 'elimination' ? `${Math.min(((profile?.current_day || 0) / 56) * 100, 100)}%` : '0%' }}></div>
            </div>
            <div style={s.plabel}>
              <span>{profile?.program_phase === 'elimination' ? `Day ${profile?.current_day || 0} of 56` : 'Complete setup to begin'}</span>
              <span>6 months total</span>
            </div>
          </div>

          {/* DAILY COMPLIANCE DISPLAY */}
          <DailyComplianceDisplay complianceData={complianceData} cleanDays={cleanDays} />

          {/* AVOIDING LIST */}
          {labResult?.foods && labResult.status !== 'pending_review' && (
            <>
              <div style={s.secLabel}>Currently avoiding</div>
              <div style={s.listCard}>
                {labResult.foods.filter(f => f.level === 'High' || f.level === 'Moderate').map((food, i, arr) => (
                  <div key={i} style={{ ...s.listItem, borderBottom: i < arr.length - 1 ? '1px solid rgba(0,0,0,0.05)' : 'none' }}>
                    <div style={s.listLeft}>
                      <div style={{ ...s.dot, background: BADGE[food.level]?.dot }}></div>
                      {food.name}
                    </div>
                    <div style={{ ...s.badge, background: BADGE[food.level]?.bg, color: BADGE[food.level]?.color }}>{food.level}</div>
                  </div>
                ))}
              </div>
            </>
          )}

          {/* AI INSIGHT */}
          <div style={s.insight}>
            <div style={s.itag}>{profile?.latest_insight ? 'AI insight' : 'Getting started'}</div>
            <div style={s.itext}>
              {profile?.latest_insight || 'Once you complete your setup and upload your lab results, the AI will start tracking your symptoms and generating personalized weekly insights.'}
            </div>
          </div>
        </div>
      )}

      {/* BOTTOM NAV */}
      <div style={s.bottomNav}>
        <div style={s.bnItem} onClick={() => { setTab('home'); setScreen('dashboard') }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={tab === 'home' ? '#3D5C3C' : '#7A7A72'} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/></svg>
          <div style={tab === 'home' ? s.bnLabelActive : s.bnLabel}>Home</div>
        </div>
        <div style={s.bnItem} onClick={() => setTab('reintro')}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={tab === 'reintro' ? '#3D5C3C' : '#7A7A72'} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
          <div style={tab === 'reintro' ? s.bnLabelActive : s.bnLabel}>Reintro</div>
        </div>
        <div style={s.bnItem} onClick={() => { setTab('checkin'); setScreen('checkin') }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={tab === 'checkin' ? '#3D5C3C' : '#7A7A72'} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
          <div style={tab === 'checkin' ? s.bnLabelActive : s.bnLabel}>Check-in</div>
        </div>
        <div style={s.bnItem} onClick={() => setTab('foodmap')}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={tab === 'foodmap' ? '#3D5C3C' : '#7A7A72'} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/><line x1="8" y1="2" x2="8" y2="18"/><line x1="16" y1="6" x2="16" y2="22"/></svg>
          <div style={tab === 'foodmap' ? s.bnLabelActive : s.bnLabel}>Food Map</div>
        </div>
      </div>
    </div>
  )
}
